t.script:
function toggleRailGroup(event, id) {
    event.stopPropagation();
    var group = document.getElementById(id);
    if (!group) return;
    var wasOpen = group.classList.contains('open');
    document.querySelectorAll('.ep-rail-group').forEach(function(g){ g.classList.remove('open'); });
    if (!wasOpen) group.classList.add('open');
}

function toggleFabMenu() {
    var menu = document.getElementById('fabMenu');
    var btn  = document.getElementById('fabCenterBtn');
    var scrim = document.getElementById('fabScrim');
    if (menu) menu.classList.toggle('show');
    if (btn)  btn.classList.toggle('fab-open');
    if (scrim) scrim.classList.toggle('show');
}

function toggleApprovalMenu() {
    var menu = document.getElementById('approvalMenu');
    if (menu) menu.classList.toggle('show');
}

function toggleEpBell(event) {
    event.stopPropagation();
    var wrap = event.currentTarget.closest('.ep-bell-wrap');
    if (!wrap) return;
    var panel = wrap.querySelector('.ep-bell-panel');
    if (!panel) return;
    var isOpen = panel.classList.contains('show');
    document.querySelectorAll('.ep-bell-panel').forEach(function(p){
        p.classList.remove('show');
    });
    if (!isOpen) panel.classList.add('show');
}

document.addEventListener('click', function(e) {
    var fab = document.getElementById('fabMenu');
    var btn = document.getElementById('fabCenterBtn');
    var scrim = document.getElementById('fabScrim');
    if (fab && !e.target.closest('#fabCenterBtn') && !e.target.closest('#fabMenu')) {
        fab.classList.remove('show');
        if (btn) btn.classList.remove('fab-open');
        if (scrim) scrim.classList.remove('show');
    }

    var app = document.getElementById('approvalMenu');
    if (app && !e.target.closest('#approvalMenu') && !e.target.closest('#approvalBtn')) {
        app.classList.remove('show');
    }

    if (!e.target.closest('.ep-bell-wrap')) {
        document.querySelectorAll('.ep-bell-panel').forEach(function(p){
            p.classList.remove('show');
        });
    }
});
